Implement the Verilog module based on the following description.
Build a 7-bit Johnson counter with synchronous active low reset signal. The Johnson counter recirculates the inverted output.
// (1) reset_n: Resets the Johnson counter to 7'b0000000 when low.
// (2) q: The current state of the Johnson counter.

module johnson_counter(
    input clk,
    input reset_n,
    output reg [6:0] q);

code:
module johnson_counter(
    input clk,
    input reset_n,
    output reg [6:0] q
);

    always @(posedge clk) begin
        if (!reset_n) begin
            // Synchronous reset: Reset the Johnson counter to 7'b0000000
            q <= 7'b0000000;
        end else begin
            // Johnson counter operation: Recirculate the inverted output
            q <= {~q[0], q[6:1]};
        end
    end

endmodule

